interface InvoiceReadRepository
{
    public function overdueForTeam(int $teamId): Collection;
}

class EloquentInvoiceReadRepository implements InvoiceReadRepository
{
    public function overdueForTeam(int $teamId): Collection
    {
        return Invoice::query()
            ->where('team_id', $teamId)
            ->wherePast('due_at')
            ->whereNull('paid_at')
            ->get();
    }
}

