class CreateOrderAction
{
    public function execute(array $data, User $user): Order
    {
        return DB::transaction(function () use ($data, $user) {
            $order = Order::create([
                ...$data,
                'created_by' => $user->id,
            ]);

            $order->items()->createMany($data['items']);

            event(new OrderPlaced($order));

            return $order;
        });
    }
}

